// Compare the signature Convex sent with the HMAC the previous node computed
// over the raw request body, in constant time, and reject stale requests.
// The secret itself never appears here: it stays in the Crypto credential.
const MAX_AGE_MS = 5 * 60 * 1000;

const received = String($json.headers['x-lendloop-signature'] ?? '').replace(/^sha256=/, '');
const expected = String($json.expectedSignature ?? '');

let mismatch = received.length ^ expected.length;
for (let i = 0; i < expected.length; i++) {
  mismatch |= expected.charCodeAt(i) ^ (received.charCodeAt(i) || 0);
}

const body = $json.body ?? {};
const age = Math.abs(Date.now() - Number(body.sentAt));

let reason = null;
if (expected.length === 0 || mismatch !== 0) reason = 'Invalid signature';
else if (!(age <= MAX_AGE_MS)) reason = 'Stale or missing timestamp';

if (reason !== null) return { json: { valid: false, reason } };

// Pass on only the fields the notification needs.
return {
  json: {
    valid: true,
    eventId: body.eventId,
    type: body.type,
    recipient: body.recipient,
    actorName: body.actorName,
    loan: body.loan,
  },
};

const { type, recipient, actorName, loan } = $json;
const dates = loan.startDate === loan.endDate
  ? loan.startDate
  : `${loan.startDate} to ${loan.endDate}`;

const templates = {
  'request.created': {
    subject: `${actorName} wants to borrow your ${loan.toolName}`,
    text: `${actorName} asked to borrow your ${loan.toolName} for ${dates}.\n\nOpen LendLoop to approve or decline the request.`,
  },
  'request.approved': {
    subject: `Your request for ${loan.toolName} was approved`,
    text: `${actorName} approved your request to borrow ${loan.toolName} for ${dates}.\n\nPlease return it by ${loan.endDate}.`,
  },
  'request.declined': {
    subject: `Your request for ${loan.toolName} was declined`,
    text: `Your request to borrow ${loan.toolName} for ${dates} was declined.`,
  },
  'request.cancelled': {
    subject: `${actorName} cancelled their request for ${loan.toolName}`,
    text: `${actorName} no longer needs your ${loan.toolName} for ${dates}. There is nothing you need to do.`,
  },
  'loan.returned': {
    subject: `${loan.toolName} marked as returned`,
    text: `${actorName} confirmed that ${loan.toolName} is back. Thanks for returning it!`,
  },
};

const template = templates[type];
if (!template) throw new Error(`Unknown event type: ${type}`);

return {
  json: {
    eventId: $json.eventId,
    to: recipient.email,
    subject: template.subject,
    text: `Hi ${recipient.name},\n\n${template.text}\n\n— LendLoop`,
  },
};
